Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
mfd: arizona: Fix regulator resource leak on
 wm5102_clear_write_sequencer() failure

The wm5102_clear_write_sequencer() helper may return an error
and just return, bypassing the cleanup sequence and causing
regulators to remain enabled, leading to a resource leak.

Change the direct return to jump to the err_reset label to
properly free the resources.

Fixes: 1c1c6bba57f5 ("mfd: wm5102: Ensure we always boot the device fully")
Signed-off-by: Haotian Zhang <vulab@iscas.ac.cn>
Reviewed-by: Charles Keepax <ckeepax@opensource.cirrus.com>
Link: https://patch.msgid.link/20251214145804.2037-1-vulab@iscas.ac.cn
Signed-off-by: Lee Jones <lee@kernel.org>

Here is the root cause:
In arizona_dev_init(), when wm5102_clear_write_sequencer() fails, the code returns directly without executing the cleanup sequence (including disabling regulators), causing a resource leak of regulators that remain enabled.

Here is the patch:

 int arizona_dev_init(struct arizona *arizona)
 {
 	static const char * const mclk_name[] = { "mclk1", "mclk2" };
 	struct device *dev = arizona->dev;
 	const char *type_name = NULL;
 	unsigned int reg, val;
 	int (*apply_patch)(struct arizona *) = NULL;
 	const struct mfd_cell *subdevs = NULL;
 	int n_subdevs = 0, ret, i;

 	dev_set_drvdata(arizona->dev, arizona);
 	mutex_init(&arizona->clk_lock);

 	if (dev_get_platdata(arizona->dev)) {
 		memcpy(&arizona->pdata, dev_get_platdata(arizona->dev),
 		       sizeof(arizona->pdata));
 	} else {
 		ret = arizona_of_get_core_pdata(arizona);
 		if (ret < 0)
 			return ret;
 	}

 	BUILD_BUG_ON(ARRAY_SIZE(arizona->mclk) != ARRAY_SIZE(mclk_name));
 	for (i = 0; i < ARRAY_SIZE(arizona->mclk); i++) {
 		arizona->mclk[i] = devm_clk_get(arizona->dev, mclk_name[i]);
 		if (IS_ERR(arizona->mclk[i])) {
 			dev_info(arizona->dev, "Failed to get %s: %ld\n",
 				 mclk_name[i], PTR_ERR(arizona->mclk[i]));
 			arizona->mclk[i] = NULL;
 		}
 	}

 	regcache_cache_only(arizona->regmap, true);

 	switch (arizona->type) {
 	case WM5102:
 	case WM5110:
 	case WM8280:
 	case WM8997:
 	case WM8998:
 	case WM1814:
 	case WM1831:
 	case CS47L24:
 		for (i = 0; i < ARRAY_SIZE(wm5102_core_supplies); i++)
 			arizona->core_supplies[i].supply
 				= wm5102_core_supplies[i];
 		arizona->num_core_supplies = ARRAY_SIZE(wm5102_core_supplies);
 		break;
 	default:
 		dev_err(arizona->dev, "Unknown device type %d\n",
 			arizona->type);
 		return -ENODEV;
 	}

 	/* Mark DCVDD as external, LDO1 driver will clear if internal */
 	arizona->external_dcvdd = true;

 	switch (arizona->type) {
 	case WM1831:
 	case CS47L24:
 		break; /* No LDO1 regulator */
 	default:
 		ret = mfd_add_devices(arizona->dev, -1, early_devs,
 				      ARRAY_SIZE(early_devs), NULL, 0, NULL);
 		if (ret != 0) {
 			dev_err(dev, "Failed to add early children: %d\n", ret);
 			return ret;
 		}
 		break;
 	}

 	ret = devm_regulator_bulk_get(dev, arizona->num_core_supplies,
 				      arizona->core_supplies);
 	if (ret != 0) {
 		dev_err(dev, "Failed to request core supplies: %d\n",
 			ret);
 		goto err_early;
 	}

 	/**
 	 * Don't use devres here because the only device we have to get
 	 * against is the MFD device and DCVDD will likely be supplied by
 	 * one of its children. Meaning that the regulator will be
 	 * destroyed by the time devres calls regulator put.
 	 */
 	arizona->dcvdd = regulator_get(arizona->dev, "DCVDD");
 	if (IS_ERR(arizona->dcvdd)) {
 		ret = PTR_ERR(arizona->dcvdd);
 		dev_err(dev, "Failed to request DCVDD: %d\n", ret);
 		goto err_early;
 	}

 	if (!arizona->pdata.reset) {
 		/* Start out with /RESET low to put the chip into reset */
 		arizona->pdata.reset = devm_gpiod_get(arizona->dev, "reset",
 						      GPIOD_OUT_LOW);
 		if (IS_ERR(arizona->pdata.reset)) {
 			ret = PTR_ERR(arizona->pdata.reset);
 			if (ret == -EPROBE_DEFER)
 				goto err_dcvdd;

 			dev_err(arizona->dev,
 				"Reset GPIO missing/malformed: %d\n", ret);

 			arizona->pdata.reset = NULL;
 		}
 	}

 	ret = regulator_bulk_enable(arizona->num_core_supplies,
 				    arizona->core_supplies);
 	if (ret != 0) {
 		dev_err(dev, "Failed to enable core supplies: %d\n",
 			ret);
 		goto err_dcvdd;
 	}

 	ret = regulator_enable(arizona->dcvdd);
 	if (ret != 0) {
 		dev_err(dev, "Failed to enable DCVDD: %d\n", ret);
 		goto err_enable;
 	}

 	arizona_disable_reset(arizona);

 	regcache_cache_only(arizona->regmap, false);

 	/* Verify that this is a chip we know about */
 	ret = regmap_read(arizona->regmap, ARIZONA_SOFTWARE_RESET, &reg);
 	if (ret != 0) {
 		dev_err(dev, "Failed to read ID register: %d\n", ret);
 		goto err_reset;
 	}

 	switch (reg) {
 	case 0x5102:
 	case 0x5110:
 	case 0x6349:
 	case 0x6363:
 	case 0x8997:
 		break;
 	default:
 		dev_err(arizona->dev, "Unknown device ID: %x\n", reg);
 		ret = -ENODEV;
 		goto err_reset;
 	}

 	/* If we have a /RESET GPIO we'll already be reset */
 	if (!arizona->pdata.reset) {
 		ret = regmap_write(arizona->regmap, ARIZONA_SOFTWARE_RESET, 0);
 		if (ret != 0) {
 			dev_err(dev, "Failed to reset device: %d\n", ret);
 			goto err_reset;
 		}

 		usleep_range(1000, 5000);
 	}

 	/* Ensure device startup is complete */
 	switch (arizona->type) {
 	case WM5102:
 		ret = regmap_read(arizona->regmap,
 				  ARIZONA_WRITE_SEQUENCER_CTRL_3, &val);
 		if (ret) {
 			dev_err(dev,
 				"Failed to check write sequencer state: %d\n",
 				ret);
 		} else if (val & 0x01) {
 			ret = wm5102_clear_write_sequencer(arizona);
 			if (ret)
-				return ret;
+				goto err_reset;
 		}
 		break;
 	default:
 		break;
 	}

 	ret = arizona_wait_for_boot(arizona);
 	if (ret) {
 		dev_err(arizona->dev, "Device failed initial boot: %d\n", ret);
 		goto err_reset;
 	}

 	/* Read the device ID information & do device specific stuff */
 	ret = regmap_read(arizona->regmap, ARIZONA_SOFTWARE_RESET, &reg);
 	if (ret != 0) {
 		dev_err(dev, "Failed to read ID register: %d\n", ret);
 		goto err_reset;
 	}

 	ret = regmap_read(arizona->regmap, ARIZONA_DEVICE_REVISION,
 			  &arizona->rev);
 	if (ret != 0) {
 		dev_err(dev, "Failed to read revision register: %d\n", ret);
 		goto err_reset;
 	}
 	arizona->rev &= ARIZONA_DEVICE_REVISION_MASK;

 	switch (reg) {
 	case 0x5102:
 		if (IS_ENABLED(CONFIG_MFD_WM5102)) {
 			type_name = "WM5102";
 			if (arizona->type != WM5102) {
 				dev_warn(arizona->dev,
 					 "WM5102 registered as %d\n",
 					 arizona->type);
 				arizona->type = WM5102;
 			}

 			apply_patch = wm5102_patch;
 			arizona->rev &= 0x7;
 			subdevs = wm5102_devs;
 			n_subdevs = ARRAY_SIZE(wm5102_devs);
 		}
 		break;
 	case 0x5110:
 		if (IS_ENABLED(CONFIG_MFD_WM5110)) {
 			switch (arizona->type) {
 			case WM5110:
 				type_name = "WM5110";
 				break;
 			case WM8280:
 				type_name = "WM8280";
 				break;
 			default:
 				type_name = "WM5110";
 				dev_warn(arizona->dev,
 					 "WM5110 registered as %d\n",
 					 arizona->type);
 				arizona->type = WM5110;
 				break;
 			}

 			apply_patch = wm5110_patch;
 			subdevs = wm5110_devs;
 			n_subdevs = ARRAY_SIZE(wm5110_devs);
 		}
 		break;
 	case 0x6363:
 		if (IS_ENABLED(CONFIG_MFD_CS47L24)) {
 			switch (arizona->type) {
 			case CS47L24:
 				type_name = "CS47L24";
 				break;

 			case WM1831:
 				type_name = "WM1831";
 				break;

 			default:
 				dev_warn(arizona->dev,
 					 "CS47L24 registered as %d\n",
 					 arizona->type);
 				arizona->type = CS47L24;
 				break;
 			}

 			apply_patch = cs47l24_patch;
 			subdevs = cs47l24_devs;
 			n_subdevs = ARRAY_SIZE(cs47l24_devs);
 		}
 		break;
 	case 0x8997:
 		if (IS_ENABLED(CONFIG_MFD_WM8997)) {
 			type_name = "WM8997";
 			if (arizona->type != WM8997) {
 				dev_warn(arizona->dev,
 					 "WM8997 registered as %d\n",
 					 arizona->type);
 				arizona->type = WM8997;
 			}

 			apply_patch = wm8997_patch;
 			subdevs = wm8997_devs;
 			n_subdevs = ARRAY_SIZE(wm8997_devs);
 		}
 		break;
 	case 0x6349:
 		if (IS_ENABLED(CONFIG_MFD_WM8998)) {
 			switch (arizona->type) {
 			case WM8998:
 				type_name = "WM8998";
 				break;

 			case WM1814:
 				type_name = "WM1814";
 				break;

 			default:
 				type_name = "WM8998";
 				dev_warn(arizona->dev,
 					 "WM8998 registered as %d\n",
 					 arizona->type);
 				arizona->type = WM8998;
 			}

 			apply_patch = wm8998_patch;
 			subdevs = wm8998_devs;
 			n_subdevs = ARRAY_SIZE(wm8998_devs);
 		}
 		break;
 	default:
 		dev_err(arizona->dev, "Unknown device ID %x\n", reg);
 		ret = -ENODEV;
 		goto err_reset;
 	}

 	if (!subdevs) {
 		dev_err(arizona->dev,
 			"No kernel support for device ID %x\n", reg);
 		ret = -ENODEV;
 		goto err_reset;
 	}

 	dev_info(dev, "%s revision %c\n", type_name, arizona->rev + 'A');

 	if (apply_patch) {
 		ret = apply_patch(arizona);
 		if (ret != 0) {
 			dev_err(arizona->dev, "Failed to apply patch: %d\n",
 				ret);
 			goto err_reset;
 		}

 		switch (arizona->type) {
 		case WM5102:
 			ret = wm5102_apply_hardware_patch(arizona);
 			if (ret) {
 				dev_err(arizona->dev,
 					"Failed to apply hardware patch: %d\n",
 					ret);
 				goto err_reset;
 			}
 			break;
 		case WM5110:
 		case WM8280:
 			ret = wm5110_apply_sleep_patch(arizona);
 			if (ret) {
 				dev_err(arizona->dev,
 					"Failed to apply sleep patch: %d\n",
 					ret);
 				goto err_reset;
 			}
 			break;
 		default:
 			break;
 		}
 	}

 	for (i = 0; i < ARRAY_SIZE(arizona->pdata.gpio_defaults); i++) {
 		if (!arizona->pdata.gpio_defaults[i])
 			continue;

 		regmap_write(arizona->regmap, ARIZONA_GPIO1_CTRL + i,
 			     arizona->pdata.gpio_defaults[i]);
 	}

 	/* Chip default */
 	if (!arizona->pdata.clk32k_src)
 		arizona->pdata.clk32k_src = ARIZONA_32KZ_MCLK2;

 	switch (arizona->pdata.clk32k_src) {
 	case ARIZONA_32KZ_MCLK1:
 	case ARIZONA_32KZ_MCLK2:
 		regmap_update_bits(arizona->regmap, ARIZONA_CLOCK_32K_1,
 				   ARIZONA_CLK_32K_SRC_MASK,
 				   arizona->pdata.clk32k_src - 1);
 		arizona_clk32k_enable(arizona);
 		break;
 	case ARIZONA_32KZ_NONE:
 		regmap_update_bits(arizona->regmap, ARIZONA_CLOCK_32K_1,
 				   ARIZONA_CLK_32K_SRC_MASK, 2);
 		break;
 	default:
 		dev_err(arizona->dev, "Invalid 32kHz clock source: %d\n",
 			arizona->pdata.clk32k_src);
 		ret = -EINVAL;
 		goto err_reset;
 	}

 	for (i = 0; i < ARIZONA_MAX_MICBIAS; i++) {
 		if (!arizona->pdata.micbias[i].mV &&
 		    !arizona->pdata.micbias[i].bypass)
 			continue;

 		/* Apply default for bypass mode */
 		if (!arizona->pdata.micbias[i].mV)
 			arizona->pdata.micbias[i].mV = 2800;

 		val = (arizona->pdata.micbias[i].mV - 1500) / 100;

 		val <<= ARIZONA_MICB1_LVL_SHIFT;

 		if (arizona->pdata.micbias[i].ext_cap)
 			val |= ARIZONA_MICB1_EXT_CAP;

 		if (arizona->pdata.micbias[i].discharge)
 			val |= ARIZONA_MICB1_DISCH;

 		if (arizona->pdata.micbias[i].soft_start)
 			val |= ARIZONA_MICB1_RATE;

 		if (arizona->pdata.micbias[i].bypass)
 			val |= ARIZONA_MICB1_BYPASS;

 		regmap_update_bits(arizona->regmap,
 				   ARIZONA_MIC_BIAS_CTRL_1 + i,
 				   ARIZONA_MICB1_LVL_MASK |
 				   ARIZONA_MICB1_EXT_CAP |
 				   ARIZONA_MICB1_DISCH |
 				   ARIZONA_MICB1_BYPASS |
 				   ARIZONA_MICB1_RATE, val);
 	}

 	pm_runtime_set_active(arizona->dev);
 	pm_runtime_enable(arizona->dev);

 	/* Set up for interrupts */
 	ret = arizona_irq_init(arizona);
 	if (ret != 0)
 		goto err_pm;

 	pm_runtime_set_autosuspend_delay(arizona->dev, 100);
 	pm_runtime_use_autosuspend(arizona->dev);

 	arizona_request_irq(arizona, ARIZONA_IRQ_CLKGEN_ERR, "CLKGEN error",
 			    arizona_clkgen_err, arizona);
 	arizona_request_irq(arizona, ARIZONA_IRQ_OVERCLOCKED, "Overclocked",
 			    arizona_overclocked, arizona);
 	arizona_request_irq(arizona, ARIZONA_IRQ_UNDERCLOCKED, "Underclocked",
 			    arizona_underclocked, arizona);

 	ret = mfd_add_devices(arizona->dev, PLATFORM_DEVID_NONE,
 			      subdevs, n_subdevs, NULL, 0, NULL);

 	if (ret) {
 		dev_err(arizona->dev, "Failed to add subdevices: %d\n", ret);
 		goto err_irq;
 	}

 	return 0;

 err_irq:
 	arizona_irq_exit(arizona);
 err_pm:
 	pm_runtime_disable(arizona->dev);

 	switch (arizona->pdata.clk32k_src) {
 	case ARIZONA_32KZ_MCLK1:
 	case ARIZONA_32KZ_MCLK2:
 		arizona_clk32k_disable(arizona);
 		break;
 	default:
 		break;
 	}
 err_reset:
 	arizona_enable_reset(arizona);
 	regulator_disable(arizona->dcvdd);
 err_enable:
 	regulator_bulk_disable(arizona->num_core_supplies,
 			       arizona->core_supplies);
 err_dcvdd:
 	regulator_put(arizona->dcvdd);
 err_early:
 	mfd_remove_devices(dev);
 	return ret;
 }
 EXPORT_SYMBOL_GPL(arizona_dev_init);


